const res = $input.first().json;
const ents = Array.isArray(res.entries) ? res.entries : [];
const list = ents.map((e, i) => {
  const cat = (e.feed && e.feed.category && e.feed.category.title) || '-';
  const feed = (e.feed && e.feed.title) || '';
  return `${i + 1}. [${cat}] ${e.title} — ${feed}
   ${e.url}`;
}).join('
');

const GENERIC_SYS = `You are the reader's research chief of staff. Their detailed profile is injected at runtime. Given the list of articles the reader starred this week, produce concise markdown with exactly these sections:
## Top 5 reads  (ranked, one line each: what it is + why it matters to their goals; pick from the list only)
## 3 post angles  (each: a specific title, 2 bullet outline, which of their skills/assets it leverages; bias to weekend-sized)
## Market signal  (one hiring / comp / tech-shift observation worth acting on)
## Weekend lab project  (one <1 weekend project that would give interview-defensible depth)`;

const envS = "You are Deep's research chief of staff.

[REDACTED IN PUBLIC REPO: reader profile - current role and seniority, target role, publishing/interview goals, and the asset/skill inventory the digest writes from. The live text is in the n8n workflow only.]

Given the list of articles Deep starred this week, produce concise markdown with exactly these sections:
## Top 5 reads
Ranked. One line each: what it is + why it moves Deep's FDE/AI-SE goal. Pick from the list only.
## 3 post angles
For each: a specific title, a 2-bullet outline, and which asset it leverages. Bias toward things he can write in a weekend.
## Market signal
One hiring / comp / tech-shift observation from the week worth acting on.
## Weekend lab project
One project (<1 weekend) that would give interview-defensible depth, tied to inference infra or AI + storage.
If nothing was starred, use the standing themes (AI + object storage, K8s inference serving, homelab automation) and still produce all four sections.";
const sys = envS.length > 40 ? envS : GENERIC_SYS;

const user = ents.length
  ? `Articles the reader starred this week (${ents.length}):

${list}`
  : `Nothing was starred this week. Use the reader's standing themes from the profile above to still produce all four sections.`;

return [{ json: { sysPrompt: sys, userMsg: user, count: ents.length } }];
